/**
 * verify-composite-state-propagation.mjs
 *
 * @version 3
 * @updated 2026-06-06
 *
 * Composite discovery is path-agnostic: a composite is any spec-bearing folder
 * matching the composite LOCATION (components/composites or feature-located
 * <feature>/components) OR declaring an explicit `tier: composite` marker in
 * spec.yaml. The marker lets composites live feature-located anywhere without a
 * hardcoded path, mirroring how the page tier keys on `tier: page`.
 *
 * Per COMPOSITE_CREATION.yaml.verifiers, refuses commits when:
 *   - spec.yaml.state_propagation declares a rule that has no corresponding implementation
 *   - composite source propagates state to an atomic NOT in consumed_atomics
 *
 * Detection: grep-based.
 *   - For each state_propagation entry, look for the prop_set_on_atomic.name being assigned
 *     on a JSX element matching the atomic_target name (case-insensitive substring match).
 *   - Cross-reference all `<AtomicName ... prop={...}>` JSX usages against consumed_atomics.
 *
 * Limitations: this is a heuristic. False positives possible when atomic name overlaps with
 * a non-atomic identifier. False negatives possible when the atomic is rendered via a variable.
 * Use it as a "did the agent forget" gate, not a proof of correctness.
 *
 * Usage:
 *   node verify-composite-state-propagation.mjs <src-root-relative-to-cwd>
 *
 * Exit: 0 green, 1 red.
 */

import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import { createRequire } from "node:module";
import { applyExceptionsByFolder } from "./_load-exceptions.mjs";

const RULE_ID = "verify-composite-state-propagation";

const RED = "\x1b[31m";
const GREEN = "\x1b[32m";
const DIM = "\x1b[2m";
const RESET = "\x1b[0m";

function loadYaml() {
  try {
    const require = createRequire(process.cwd() + "/");
    return require("yaml");
  } catch {
    return null;
  }
}

function fail(msg) {
  process.stderr.write(`${RED}❌ verify-composite-state-propagation:${RESET} ${msg}\n`);
  process.exit(1);
}

function ok(msg) {
  process.stdout.write(`${GREEN}✅ verify-composite-state-propagation${RESET} — ${msg}\n`);
}

function findCompositeRoots(srcRoot) {
  const found = [];
  const queue = [srcRoot];
  while (queue.length > 0) {
    const dir = queue.shift();
    if (!fs.existsSync(dir)) continue;
    let entries;
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const e of entries) {
      if (!e.isDirectory()) continue;
      if (e.name === "node_modules" || e.name.startsWith(".")) continue;
      const full = path.join(dir, e.name);
      const specPath = path.join(full, "__specs__", "spec.yaml");
      if (fs.existsSync(specPath)) {
        // A composite is identified EITHER by location (components/composites or a
        // feature-located <feature>/components folder) OR — path-agnostic, consistent
        // with how the page tier keys on `tier: page` — by an explicit
        // `tier: composite` marker in spec.yaml. The marker lets a composite live
        // anywhere (e.g. feature-located form/components/<X>) with no hardcoded path,
        // and never false-positives on an atomic (whose spec omits `tier: composite`).
        const byLocation =
          full.includes(path.sep + "components" + path.sep + "composites") ||
          full.match(new RegExp(`features\\${path.sep}[^${path.sep}]+\\${path.sep}components`));
        let byMarker = false;
        try {
          byMarker = /^\s*tier:\s*composite\s*$/m.test(fs.readFileSync(specPath, "utf8"));
        } catch {
          byMarker = false;
        }
        if (byLocation || byMarker) {
          found.push(full);
          continue;
        }
      }
      queue.push(full);
    }
  }
  return found;
}

function collectSources(compositeFolder) {
  const sources = [];
  function walk(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) {
        if (e.name === "__specs__" || e.name === "__tests__" || e.name === "__stories__") continue;
        walk(path.join(dir, e.name));
      } else if (/\.tsx$/.test(e.name)) {
        sources.push(path.join(dir, e.name));
      }
    }
  }
  walk(compositeFolder);
  return sources;
}

function atomicNameFromPath(atomicPath) {
  if (!atomicPath) return null;
  return atomicPath.replace(/\\/g, "/").split("/").pop();
}

function main() {
  const arg = process.argv[2] || "src";
  const srcRoot = path.resolve(process.cwd(), arg);
  if (!fs.existsSync(srcRoot)) {
    ok(`no ${arg} dir; nothing to verify.`);
    return;
  }

  const yaml = loadYaml();
  if (!yaml) {
    fail("cannot resolve `yaml` package. Install it: pnpm add -Dw yaml");
  }

  const composites = findCompositeRoots(srcRoot);
  if (composites.length === 0) {
    ok(`no composite folders found under ${arg}; nothing to verify.`);
    return;
  }

  const allViolations = [];

  for (const compositeFolder of composites) {
    const specPath = path.join(compositeFolder, "__specs__", "spec.yaml");
    let spec;
    try {
      spec = yaml.parse(fs.readFileSync(specPath, "utf8"));
    } catch {
      continue;
    }
    if (spec?.tier !== "composite") continue;

    const consumed = Array.isArray(spec.consumed_atomics) ? spec.consumed_atomics : [];
    const consumedNames = new Set(
      consumed.map((a) => atomicNameFromPath(a.path)).filter(Boolean),
    );
    // consumed_atomics paths are kebab-case folder tails (e.g. "inspect-toggle"),
    // but JSX usages are PascalCase component names ("InspectToggle"). Normalize
    // both to hyphen-stripped lowercase so a declared atomic is recognized by its
    // rendered component name regardless of case/separator convention.
    const normalizeName = (n) => n.replace(/-/g, "").toLowerCase();
    const consumedNamesNorm = new Set([...consumedNames].map(normalizeName));

    const propagation = Array.isArray(spec.state_propagation) ? spec.state_propagation : [];
    const sources = collectSources(compositeFolder);
    const combinedSource = sources.map((p) => fs.readFileSync(p, "utf8")).join("\n");

    for (const rule of propagation) {
      const target = rule.atomic_target;
      const propName = rule.prop_set_on_atomic;
      if (!target || !propName) continue;
      if (target.toLowerCase().includes("(no") || target === "n/a") continue;

      const atomicName = consumed.find(
        (a) => atomicNameFromPath(a.path) === target,
      )
        ? target
        : consumed.find(
            (a) =>
              atomicNameFromPath(a.path)?.toLowerCase() === target.toLowerCase(),
          )?.path?.split("/")?.pop() ?? target;

      const propRegex = new RegExp(
        `<\\s*${atomicName}\\b[^>]*\\b${propName}\\b`,
        "i",
      );
      if (!propRegex.test(combinedSource)) {
        allViolations.push({
          folder: compositeFolder,
          rule: `state_propagation declares "${rule.composite_state}" → ${atomicName}.${propName} but source has no <${atomicName} ... ${propName}=...> assignment`,
        });
      }
    }

    const jsxElementRegex = /<\s*([A-Z][A-Za-z0-9_]*)\b/g;
    const usedAtomicNames = new Set();
    for (const m of combinedSource.matchAll(jsxElementRegex)) {
      usedAtomicNames.add(m[1]);
    }
    for (const used of usedAtomicNames) {
      if (used.startsWith(spec.component ?? "X")) continue;
      if (/^(Fragment|StrictMode|Suspense|Provider|Consumer)$/.test(used)) continue;
      if (consumedNames.has(used)) continue;
      if (consumedNamesNorm.has(normalizeName(used))) continue;
      const isAtomicLike =
        /Button|Select|Input|Dialog|Drawer|Tooltip|Badge|Card|Tabs|Progress|Alert|Banner|Spinner|StateMessage|ListRow|Switch|Toggle|Checkbox|Textarea|Label|Separator|Sonner|Accordion/.test(
          used,
        );
      if (isAtomicLike) {
        allViolations.push({
          folder: compositeFolder,
          rule: `source renders <${used}> but it is NOT in spec.yaml.consumed_atomics — add it or remove the usage`,
        });
      }
    }
  }

  // Apply per-feature exception.yaml waivers (logs each accepted waiver + reason).
  const survivors = applyExceptionsByFolder(allViolations, RULE_ID, process.cwd());
  allViolations.length = 0;
  allViolations.push(...survivors);

  if (allViolations.length === 0) {
    ok(
      `${composites.length} composite(s) checked; all state_propagation rules implemented + consumed_atomics match source.`,
    );
    return;
  }

  process.stderr.write(
    `${RED}❌ verify-composite-state-propagation:${RESET} ${allViolations.length} violation(s)\n\n`,
  );
  for (const v of allViolations) {
    process.stderr.write(
      `  ${path.relative(process.cwd(), v.folder)}:\n    rule: ${v.rule}\n\n`,
    );
  }
  process.stderr.write(
    `${DIM}Per COMPOSITE_CREATION.yaml, declared state_propagation rules must be implemented; every JSX atomic must appear in consumed_atomics.${RESET}\n`,
  );
  process.exit(1);
}

main();
